// Response shape: { stats: { new_subscribers, cancellations,
//   net_new_subscribers, subscribers, starting, ending } }
// Note: `subscribers` is a point-in-time total as of `ending`,
// not a sum over the week.
const s = $input.first().json.stats ?? {};
const arrow = (s.net_new_subscribers ?? 0) > 0 ? '📈' : (s.net_new_subscribers ?? 0) < 0 ? '📉' : '➖';
const sign = (n) => (n > 0 ? `+${n}` : `${n}`);

const message =
  `${arrow} Newsletter week in numbers\n` +
  `New subscribers: ${s.new_subscribers ?? 0}\n` +
  `Cancellations: ${s.cancellations ?? 0}\n` +
  `Net: ${sign(s.net_new_subscribers ?? 0)}\n` +
  `List total: ${s.subscribers ?? '?'} active`;

return [{ json: { message } }];
